  "sql": "SELECT DISTINCT cs.canonical_smiles, md_sub.pref_name AS substrate_compound_name, md_par.pref_name AS parent_compound_name, m.met_conversion, m.pathway_key, m.organism, m.enzyme_name FROM metabolism m INNER JOIN compound_records cr_sub ON m.substrate_record_id = cr_sub.record_id INNER JOIN molecule_dictionary md_sub ON cr_sub.molregno = md_sub.molregno INNER JOIN compound_structures cs ON md_sub.molregno = cs.molregno LEFT JOIN compound_records cr_par ON m.drug_record_id = cr_par.record_id LEFT JOIN molecule_dictionary md_par ON cr_par.molregno = md_par.molregno WHERE m.enzyme_name = 'CYP2C19' ORDER BY cs.canonical_smiles ASC, md_sub.pref_name ASC, md_par.pref_name ASC, m.met_conversion ASC, m.pathway_key ASC, m.organism ASC, m.enzyme_name ASC LIMIT 200"
